extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var crate := await instantiate_scene("res://crate.tscn") as Node2D
	if not check("crate_load", crate != null, "La scena res://crate.tscn deve caricarsi ed essere istanziata"):
		return

	var health := find_by_name(crate, "Health") as Health
	if not check("health_node", health != null, "La cassa deve contenere un nodo Health"):
		return

	var hurtbox := find_by_name(crate, "Hurtbox") as Area2D
	if not check("hurtbox_node", hurtbox != null, "La cassa deve contenere un nodo Hurtbox"):
		return

	var linked_health = get_prop(hurtbox, "health_component")
	check("hurtbox_linked", linked_health == health, "Il nodo Hurtbox deve avere la proprietà health_component collegata al nodo Health")

	call_if_exists(health, "take_damage", [1])
	await wait_frames(2)
	check("color_changed", crate.modulate != Color.WHITE, "Dopo il primo colpo la cassa deve modulare il colore")

	call_if_exists(health, "take_damage", [1])
	await wait_frames(2)
	var destroyed := not is_instance_valid(crate) or crate.is_queued_for_deletion()
	check("crate_destroyed", destroyed, "A zero punti vita la cassa deve chiamare queue_free()")

